const key='brujula-single-user-drafts-v1';
function read(){try{return JSON.parse(localStorage.getItem(key))||{};}catch{return {};}}
function store(all){try{localStorage.setItem(key,JSON.stringify(all));const status=document.querySelector('#save-status');if(status)status.textContent='Perfil único · Guardado en este navegador';}catch{const status=document.querySelector('#save-status');if(status)status.textContent='No se pudo guardar: descarga tu resumen';}}
export function bindDrafts(){for(const form of document.querySelectorAll('form[id]')){let saved=read()[form.id];const currency=form.elements.namedItem('_currency');if(saved?._currency&&currency&&saved._currency!==currency.value){const all=read();delete all[form.id];store(all);saved=null;}if(saved)for(const [name,value] of Object.entries(saved)){const input=form.elements.namedItem(name);if(input)input.value=value;}const capture=()=>{const all=read();all[form.id]=Object.fromEntries(new FormData(form));store(all);};form.addEventListener('input',capture);form.addEventListener('change',capture);form.addEventListener('submit',()=>{if(form.id==='chat-form'){const all=read();delete all[form.id];store(all);}},true);}}
export function updateDraft(formId,values){const all=read();all[formId]={...(all[formId]||{}),...values};store(all);}
export function clearDrafts(){try{localStorage.removeItem(key);}catch{}}
export function exportDrafts(){return read();}
